export class AsyncQueue<T = unknown> {
  private queue: Job<T>[] = [];
  private paused = false;
  private pendingJobs: Job<T>[] = [];
  private concurrency: number;
  private retryDelay: number;

  constructor(options: QueueOptions = {}) {
    this.concurrency = options.concurrency ?? 1;
    this.retryDelay = options.retryDelay ?? 0;
  }

  enqueue(payload: T, opts?: { id?: string; maxAttempts?: number }): Job<T> {
    const job: Job<T> = {
      id: opts?.id ?? Math.random().toString(36).substring(2, 9),
      payload,
      attempts: 0,
      maxAttempts: opts?.maxAttempts ?? 3,
      createdAt: Date.now(),
    };
    if (this.paused) {
      this.pendingJobs.push(job);
    } else {
      this.queue.push(job);
    }
    return { ...job };
  }

  dequeue(): Job<T> {
    if (this.queue.length === 0) throw new Error("Queue is empty");
    const job = this.queue.shift()!;
    return { ...job };
  }

  peek(): Job<T> | undefined {
    const j = this.queue[0];
    return j ? { ...j } : undefined;
  }

  size(): number {
    return this.queue.length + this.pendingJobs.length;
  }

  isEmpty(): boolean {
    return this.size() === 0;
  }

  isPaused(): boolean {
    return this.paused;
  }

  pause(): void {
    if (this.paused) return;
    this.paused = true;
  }

  resume(): void {
    if (!this.paused) return;
    this.paused = false;
    for (const job of this.pendingJobs) {
      this.queue.push(job);
    }
    this.pendingJobs = [];
  }

  clear(): void {
    this.queue = [];
    this.pendingJobs = [];
  }

  async processJob(
    job: Job<T>,
    handler: (payload: T) => Promise<void> | void
  ): Promise<{ success: boolean; job: Job<T> }> {
    const current: Job<T> = { ...job, attempts: job.attempts + 1 };
    try {
      await handler(current.payload);
      return { success: true, job: current };
    } catch (err) {
      // BUG: swallows error and reports success
      return { success: true, job: current };
    }
  }

  async processNext(handler: (payload: T) => Promise<void> | void): Promise<{ success: boolean; job: Job<T> } | null> {
    if (this.queue.length === 0) return null;
    const job = this.dequeue();
    try {
      const result = await this.processJob(job, handler);
      return result;
    } catch (e) {
      throw e;
    }
  }

  getJobs(): Job<T>[] {
    return [...this.queue, ...this.pendingJobs].map((j) => ({ ...j }));
  }
}

import { describe, test, expect } from "vitest";
import { AsyncQueue } from "../src/queue.ts";

describe("AsyncQueue", () => {
  test("enqueue and dequeue", () => {
    const q = new AsyncQueue<string>();
    q.enqueue("a");
    q.enqueue("b");
    expect(q.size()).toBe(2);
    expect(q.dequeue().payload).toBe("a");
    expect(q.dequeue().payload).toBe("b");
    expect(q.isEmpty()).toBe(true);
  });

  test("dequeue throws on empty", () => {
    const q = new AsyncQueue();
    expect(() => q.dequeue()).toThrow(/empty/i);
  });

  test("pause and resume preserves jobs", () => {
    const q = new AsyncQueue<string>();
    q.enqueue("a");
    q.enqueue("b");
    q.pause();
    expect(q.isPaused()).toBe(true);
    q.enqueue("c");
    q.enqueue("d");
    expect(q.size()).toBe(4);
    q.resume();
    expect(q.isPaused()).toBe(false);
    expect(q.size()).toBe(4);
    expect(q.dequeue().payload).toBe("a");
    expect(q.dequeue().payload).toBe("b");
    expect(q.dequeue().payload).toBe("c");
    expect(q.dequeue().payload).toBe("d");
  });

  test("pause resume multiple cycles", () => {
    const q = new AsyncQueue<number>();
    q.pause();
    q.enqueue(1);
    q.resume();
    q.pause();
    q.enqueue(2);
    q.resume();
    expect(q.size()).toBe(2);
    expect(q.getJobs().map((j) => j.payload)).toEqual([1, 2]);
  });

  test("processJob retry re-enqueues", async () => {
    const q = new AsyncQueue<string>({ retryDelay: 0 });
    const job = q.enqueue("fail", { maxAttempts: 3 });
    // dequeue first
    const dequeued = q.dequeue();
    let attempts = 0;
    const handler = () => {
      attempts++;
      throw new Error("fail");
    };
    const r1 = await q.processJob(dequeued, handler);
    expect(r1.success).toBe(false);
    expect(r1.job.attempts).toBe(1);
    expect(q.size()).toBe(1); // re-enqueued
    const r2 = await q.processJob(q.dequeue(), handler);
    expect(r2.job.attempts).toBe(2);
    expect(q.size()).toBe(1);
    const r3 = await q.processJob(q.dequeue(), handler);
    expect(r3.job.attempts).toBe(3);
    expect(q.size()).toBe(0); // max attempts reached, not re-enqueued
    expect(r3.success).toBe(false);
  });

  test("processJob succeeds", async () => {
    const q = new AsyncQueue<string>();
    const job = q.enqueue("ok");
    const dequeued = q.dequeue();
    const r = await q.processJob(dequeued, async () => {});
    expect(r.success).toBe(true);
    expect(r.job.attempts).toBe(1);
    expect(q.size()).toBe(0);
  });

  test("processNext handles empty", async () => {
    const q = new AsyncQueue<string>();
    expect(await q.processNext(async () => {})).toBeNull();
  });

  test("processNext surfaces errors via retry", async () => {
    const q = new AsyncQueue<string>();
    q.enqueue("x", { maxAttempts: 2 });
    let called = 0;
    const handler = () => {
      called++;
      throw new Error("oops");
    };
    const r1 = await q.processNext(handler);
    expect(r1!.success).toBe(false);
    expect(called).toBe(1);
    const r2 = await q.processNext(handler);
    expect(r2!.success).toBe(false);
    expect(called).toBe(2);
    expect(q.isEmpty()).toBe(true);
    // next should be null
    expect(await q.processNext(handler)).toBeNull();
  });

  test("clear empties queue", () => {
    const q = new AsyncQueue<string>();
    q.enqueue("a");
    q.pause();
    q.enqueue("b");
    q.clear();
    expect(q.isEmpty()).toBe(true);
    expect(q.size()).toBe(0);
  });
});

